// === Tab: mySketch ===
let stars = [];
let num = 150;

function setup(){
    createCanvas(700, 700);

    for(let i=0; i<num; i++){
        stars.push(new Star());
    }
}

function draw(){
    background(0);

    for(let i=0; i<stars.length; i++){
        stars[i].update();
        stars[i].show();
        for(let j=0; j<stars.length; j++){
            if(i>j){
                let d = stars[i].pos.dist(stars[j].pos);
                if(d <= width/10){
                    stroke(255,100);
                    strokeWeight(0.75);
                    line(stars[i].pos.x, stars[i].pos.y, stars[j].pos.x, stars[j].pos.y);
                }
            }
        }
    }
}

class Star {
    constructor(){
        this.a = random(5 * TAU);
        this.r = (width * 0.2, width * 0.25);
        this.pos = createVector(width/2 + cos(this.a)*this.r, height/2 + sin(this.a)*this.r);
        this.vel = p5.Vector.random2D();
        this.acc = p5.Vector.random2D();
        this.m;     
    }

    update(){
        this.acc.mult(0.45);
        this.vel.add(this.acc);  

        let len = dist(this.pos.x, this.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
        this.m = constrain( map(len, 0, width, 6, 0.05), 0.05, 6 );
        this.vel.normalize().mult(this.m);

        if( dist(this.pos.x, this.pos.y, width/2, height/2) > width/2 * 0.8 ){
            if(this.pos.x < width/2){
                this.pos.x = width - this.pos.x -4;
            } else if(this.pos.x > width/2){
                this.pos.x = width - this.pos.x +4;
            }
            if(this.pos.y < height/2){
                this.pos.y = height - this.pos.y -4;
            } else if(this.pos.y > height/2){
                this.pos.y = height - this.pos.y +4;
            }
        }
        this.pos.add(this.vel);
    }

    show(){
        noStroke();
        fill(255);
        ellipse(this.pos.x, this.pos.y, 2);
    }
}

